import{_ as t,H as a,f as n,i as s}from"./chunks/framework.B3xCVCEH.js";const o="/docs/assets/manage-assertions-button.rFKAnPpL.png",i="/docs/assets/stop-managing-assertions.BydceOc6.png",r="data:image/png;base64,",d="/docs/assets/assertion-editor-controls.CADrbCZj.png",g="/docs/assets/assertion-editor-add-evidence.BySAmGV_.png",m="/docs/assets/assertion-editor-view-evidence.CeWENtcy.png",l="/docs/assets/assertion-editor-remove-assertion.B7-lYG8U.png",c="/docs/assets/assertion-editor-add-badge.uu807120.png",p="/docs/assets/assertion-editor-view-badge.BElik_U_.png",E=JSON.parse('{"title":"Creating and Editing","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/assertions/managing-assertions/index.md","filePath":"authoring/assertions/managing-assertions/README.md"}'),A={name:"authoring/assertions/managing-assertions/index.md"};function h(u,e,b,v,y,f){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="creating-and-editing" tabindex="-1">Creating and Editing <a class="header-anchor" href="#creating-and-editing" aria-label="Permalink to &quot;Creating and Editing&quot;">​</a></h1><p><strong>Assertion management is only available to logged in users, ensure you are logged in to the application before continuing.</strong></p><h2 id="enabling-assertion-management" tabindex="-1">Enabling Assertion Management <a class="header-anchor" href="#enabling-assertion-management" aria-label="Permalink to &quot;Enabling Assertion Management&quot;">​</a></h2><p>Open any framework and you should be presented with a <em>manage assertions</em> button in the top toolbar</p><p><img src="'+o+'" alt="Manage Assertions Button"></p><p>To return to the framework editing mode, simply press the <em>stop managing assertions</em> button in the top toolbar</p><p><img src="'+i+'" alt="Stop Managing Assertions Button"></p><h2 id="choosing-a-subject" tabindex="-1">Choosing a Subject <a class="header-anchor" href="#choosing-a-subject" aria-label="Permalink to &quot;Choosing a Subject&quot;">​</a></h2><p>You can choose to make assertions about yourself, or another user in the system. In order to change the subject of your assertions, click the <em>myself</em> button and select a new user from the resulting dialog.</p><p><img src="'+r+'" alt="Select Assertion Subject Button"></p><h2 id="creating-an-assertion" tabindex="-1">Creating an Assertion <a class="header-anchor" href="#creating-an-assertion" aria-label="Permalink to &quot;Creating an Assertion&quot;">​</a></h2><p>Once in the assertion management mode, the competencies in the framework will display new controls to create either a positive or negative assertion, indicating that a user can or cannot perform the competency respectively.</p><p><img src="'+d+'" alt="Assertion Editor Controls"></p><p>Clicking the <em>I can</em> button will generate a positive assertion for that competency and display an input field allowing you to provide evidence in the form of text or a link to support the assertion. Press <em>enter</em> on your keyboard after entering the evidence into the input field to attach it to your assertion.</p><p><img src="'+g+'" alt="Assertion Editor Add Evidence"></p><p>The evidence will appear in a section underneath the input field, along with a button to delete that evidence if desired.</p><p><img src="'+m+'" alt="Assertion Editor View Evidence"></p><h2 id="deleting-an-assertion" tabindex="-1">Deleting an Assertion <a class="header-anchor" href="#deleting-an-assertion" aria-label="Permalink to &quot;Deleting an Assertion&quot;">​</a></h2><p>To delete an assertion, simply click the same button that was used to create the assertion. In this case, the <em>I can</em> button.</p><p><img src="'+l+'" alt="Assertion Editor Remove Assertion"></p><h2 id="adding-a-badge" tabindex="-1">Adding a Badge <a class="header-anchor" href="#adding-a-badge" aria-label="Permalink to &quot;Adding a Badge&quot;">​</a></h2><p>You can add a badge to a positive assertion by clicking the <em>add badge</em> button.</p><p><img src="'+c+'" alt="Assertion Editor Add Badge"></p><p>This will generate a url for the badge that can be viewed by clicking the <em>view badge</em> button and then shared.</p><p><img src="'+p+'" alt="Assertion Editor View Badge"></p>',25)])])}const U=t(A,[["render",h]]);export{E as __pageData,U as default};
